$after=[];foreach(['campaigns','items']as$t)$after[$t]=$wpdb->get_results('SELECT * FROM '.$wpdb->prefix.'exin_bf_'.$t.' ORDER BY 1,2',ARRAY_A);ready_assert($before===$after,'Analytics/replay changed frozen campaign/item data');
$parts=array_column($report['result'],'measurement','role');$refund_at=$parts['updates']['result']['refund_finished_unix'];ready_assert($parts['analytics']['started_unix']<=$refund_at&&$refund_at<=$parts['analytics']['finished_unix'],'Refund did not overlap live analytics worker');$out=['initial_sales_units'=>$initial_units,'refund_during_live_analytics'=>true,'result'=>'PASS','products'=>1738,'overlap'=>$report,'units_after_concurrent_refund'=>$units,'distinct_orders'=>$orders,'campaigns_items_unchanged'=>true];file_put_contents($root.'/work/v140/readiness-overlap.json',wp_json_encode($out,JSON_PRETTY_PRINT));echo 'EXIN_READY_OVERLAP '.wp_json_encode($out).PHP_EOL;
